/bin/zsh -lc "set -e
perl -0777 -ne 'if (/<script type=\"module\">(.*?)<\\/script>/s) { print "'$1 }'"' index.html | node --input-type=module --check
test \""'$(rg -c '"'<title>GPT-5\\.6 Sol</title>' index.html)\" -eq 1
test \""'$(rg -c '"'<h1>GPT-5\\.6 Sol</h1>' index.html)\" -eq 1
test \""'$(rg -c '"'data-system=' index.html)\" -eq 4
test \""'$(rg -c '"'data-mode=' index.html)\" -eq 4

chrome=\"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome\"
test -x \""'$chrome"
profile="$(mktemp -d /tmp/ac-validation.XXXXXX)"
python3 -m http.server 9137 --bind 127.0.0.1 >/tmp/ac-validation-server.log 2>&1 &
server_pid=$!
"$chrome" --headless=new --no-sandbox --enable-webgl --ignore-gpu-blocklist --enable-unsafe-swiftshader --use-angle=swiftshader --remote-debugging-port=9138 --user-data-dir="$profile" --no-first-run --no-default-browser-check http://127.0.0.1:9137/index.html >/tmp/ac-validation-chrome.log 2>&1 &
chrome_pid=$!
cleanup() {
  kill "$chrome_pid" "$server_pid" 2>/dev/null || true
  trash "$profile" 2>/dev/null || true
}
trap cleanup EXIT
for attempt in {1..30}; do
  if curl -fsS http://127.0.0.1:9138/json/list >/tmp/ac-validation-tabs.json 2>/dev/null; then break; fi
  sleep .25
done

node --input-type=module <<'"'NODE'
const tabs = await fetch('http://127.0.0.1:9138/json/list').then(r => r.json());
const page = tabs.find(tab => tab.type === 'page');
if ("'!page) throw new Error('"'No browser page available');
const socket = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  socket.addEventListener('open', resolve, { once: true });
  socket.addEventListener('error', reject, { once: true });
});
let id = 0;
const pending = new Map();
const exceptions = [];
socket.addEventListener('message', event => {
  const message = JSON.parse(event.data);
  if (message.method === 'Runtime.exceptionThrown') exceptions.push(message.params.exceptionDetails.text);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    message.error ? reject(new Error(message.error.message)) : resolve(message.result);
  }
});
function send(method, params = {}) {
  const requestId = ++id;
  socket.send(JSON.stringify({ id: requestId, method, params }));
  return new Promise((resolve, reject) => pending.set(requestId, { resolve, reject }));
}
async function evaluate(expression) {
  const reply = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (reply.exceptionDetails) throw new Error(reply.exceptionDetails.text);
  return reply.result.value;
}
await send('Runtime.enable');
let loaded = false;
for (let attempt = 0; attempt < 40; attempt++) {
  loaded = await evaluate(\"Boolean(document.querySelector('#stage canvas'))\");
  if (loaded) break;
  await new Promise(resolve => setTimeout(resolve, 250));
}
if ("'!loaded) throw new Error('"'Three.js canvas did not load');
const expression = '(() => { document.querySelector(\"[data-system=mono]\").click(); document.querySelector(\"[data-mode=heating]\").click(); document.querySelector(\"#play\").click(); document.querySelector(\"#reset\").click(); document.querySelector(\"#tour\").click(); return { state: document.querySelector(\"#state-value\").textContent, room: document.querySelector(\"#room-temp\").textContent, outdoor: document.querySelector(\"#outdoor-temp\").textContent, monoPressed: document.querySelector(\"[data-system=mono]\").getAttribute(\"aria-pressed\"), heatingPressed: document.querySelector(\"[data-mode=heating]\").getAttribute(\"aria-pressed\"), playLabel: document.querySelector(\"#play\").getAttribute(\"aria-label\"), tutorialVisible: "'!document.querySelector("#tutorial").hidden, tutorialCopy: document.querySelector("#tutorial-copy").textContent.length > 20, fatalVisible: getComputedStyle(document.querySelector("#fatal")).display !== "none" }; })()'"';
const result = await evaluate(expression);
const expected = result.state === 'Monoblock · Heating'
  && result.room === '21 °C'
  && result.outdoor === '5 °C'
  && result.monoPressed === 'true'
  && result.heatingPressed === 'true'
  && result.playLabel === 'Play animation'
  && result.tutorialVisible
  && result.tutorialCopy
  && "'!result.fatalVisible;
if (!expected || exceptions.length) {
  throw new Error(JSON.stringify({ result, exceptions }));
}
socket.close();
console.log(JSON.stringify({ syntax: '"'ok', pageLoad: 'ok', controls: 'ok', result }));
NODE"

